patch:
diff --git a/tests/repro/cross-drive-ignore.js b/tests/repro/cross-drive-ignore.js
new file mode 100644
index 0000000..e95a98d
--- /dev/null
+++ b/tests/repro/cross-drive-ignore.js
@@ -0,0 +1,60 @@
+/**
+ * Reproduction for "files on a different drive are not ignored on Windows".
+ *
+ * Runs on any OS: `path`/`node:path` are swapped for `path.win32` and
+ * process.cwd() is pinned to a Windows directory on drive C: before ESLint
+ * is loaded, so ESLint and @eslint/config-array use Windows path semantics.
+ * On real Windows the shim is a no-op apart from the fixed cwd.
+ */
+"use strict";
+
+const Module = require("node:module");
+const path = require("node:path");
+
+const CWD = "C:\\Project";
+const originalLoad = Module._load;
+
+Module._load = function(request, ...rest) {
+    if (request === "path" || request === "node:path") {
+        return path.win32;
+    }
+    return originalLoad.call(this, request, ...rest);
+};
+process.cwd = () => CWD;
+
+const { Linter, ESLint } = require("../../lib/api");
+
+const code = "foo();";
+const config = { rules: { "no-undef": "error" } };
+const cases = [
+    ["inside cwd (control: linted)", `${CWD}\\foo.js`],
+    ["same drive, outside cwd (control: not linted)", "C:\\Other\\foo.js"],
+    ["different drive (BUG if linted)", "F:\\foo.js"]
+];
+
+(async () => {
+    console.log(`cwd=${process.cwd()}  path.relative(cwd, "F:\\\\foo.js") = ${JSON.stringify(path.win32.relative(CWD, "F:\\foo.js"))}\n`);
+
+    const linter = new Linter({ configType: "flat", cwd: CWD });
+    const eslint = new ESLint({ cwd: CWD, overrideConfigFile: true, overrideConfig: config });
+    let bug = false;
+
+    for (const [label, file] of cases) {
+        const linterMsgs = linter.verify(code, config, file).map(m => m.ruleId || m.message);
+        const ignored = await eslint.isPathIgnored(file);
+        const [result] = await eslint.lintText(code, { filePath: file, warnIgnored: true });
+        const lintTextMsgs = result.messages.map(m => m.ruleId || m.message);
+
+        console.log(label, "-", file);
+        console.log("  Linter#verify         :", linterMsgs);
+        console.log("  ESLint#isPathIgnored  :", ignored);
+        console.log("  ESLint#lintText       :", lintTextMsgs, "\n");
+
+        if (file.startsWith("F:") && (linterMsgs.includes("no-undef") || !ignored || lintTextMsgs.includes("no-undef"))) {
+            bug = true;
+        }
+    }
+
+    console.log(bug ? "BUG REPRODUCED: F:\\foo.js is linted instead of being ignored." : "Not reproduced.");
+    process.exitCode = bug ? 1 : 0;
+})();
